cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef EPS
#define EPS 1e-5f
#endif

// BLOCK_SIZE must be a power of two and ≤ 1024
template <int BLOCK_SIZE>
__global__ void groupnorm_kernel(
    const __half* __restrict__ inp,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ out,
    int B, int C, int H, int W,
    int G, float eps)
{
    // each block handles one (batch, group) pair
    int batch_idx = blockIdx.x / G;
    int group_idx = blockIdx.x % G;

    int C_per_g = C / G;                 // channels per group
    int S = H * W;                       // spatial size per channel
    int N = C_per_g * S;                 // elements per (batch, group)

    int tid = threadIdx.x;

    // ---------- first pass: compute sum and sum of squares ----------
    float sum = 0.0f;
    float sumsq = 0.0f;

    // grid‑stride loop over the N elements belonging to this (batch,group)
    for (int i = tid; i < N; i += BLOCK_SIZE) {
        int c_off = i / S;          // channel offset inside the group
        int s_off = i % S;          // spatial offset

        int c = group_idx * C_per_g + c_off;   // absolute channel index
        int h = s_off / W;
        int w = s_off % W;

        // NCHW flat index
        int idx = ((batch_idx * C + c) * H + h) * W + w;

        float v = __half2float(inp[idx]);
        sum   += v;
        sumsq += v * v;
    }

    // ---------- block‑wide reduction ----------
    __shared__ float sh_sum[BLOCK_SIZE];
    __shared__ float sh_sumsq[BLOCK_SIZE];

    sh_sum[tid]   = sum;
    sh_sumsq[tid] = sumsq;
    __syncthreads();

    // tree reduction (assumes BLOCK_SIZE is power of two)
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sh_sum[tid]   += sh_sum[tid + stride];
            sh_sumsq[tid] += sh_sumsq[tid + stride];
        }
        __syncthreads();
    }

    float mean, inv_std;
    if (tid == 0) {
        float block_sum   = sh_sum[0];
        float block_sumsq = sh_sumsq[0];
        mean   = block_sum / static_cast<float>(N);
        float var = block_sumsq / static_cast<float>(N) - mean * mean;
        inv_std = rsqrtf(var + eps);
        // store for other threads
        sh_sum[0]   = mean;
        sh_sumsq[0] = inv_std;
    }
    __syncthreads();
    mean    = sh_sum[0];
    inv_std = sh_sumsq[0];

    // ---------- second pass: normalize and apply affine ----------
    for (int i = tid; i < N; i += BLOCK_SIZE) {
        int c_off = i / S;
        int s_off = i % S;

        int c = group_idx * C_per_g + c_off;
        int h = s_off / W;
        int w = s_off % W;

        int idx = ((batch_idx * C + c) * H + h) * W + w;

        float v = __half2float(inp[idx]);
        float norm = (v - mean) * inv_std;

        float wgt = __half2float(weight[c]);
        float bsn = __half2float(bias[c]);

        float out_val = norm * wgt + bsn;
        out[idx] = __float2half(out_val);
    }
}

// ------------------------------------------------------------------
// Wrapper called from Python
// ------------------------------------------------------------------
torch::Tensor groupnorm_cuda(torch::Tensor input,
                             torch::Tensor weight,
                             torch::Tensor bias,
                             int64_t num_groups,
                             double eps_double) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
    TORCH_CHECK(input.dtype() == torch::kFloat16, "input must be float16");
    TORCH_CHECK(weight.dtype() == torch::kFloat16 && bias.dtype() == torch::kFloat16,
                "weight/bias must be float16");
    TORCH_CHECK(input.dim() == 4, "input must be 4-D (NCHW)");

    const int B = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);
    const int G = static_cast<int>(num_groups);
    TORCH_CHECK(C % G == 0, "num_channels must be divisible by num_groups");

    auto output = torch::empty_like(input);

    constexpr int BLOCK_SIZE = 256;          // power‑of‑two, ≤ 1024
    dim3 block(BLOCK_SIZE);
    dim3 grid(B * G);
    float eps = static_cast<float>(eps_double);

    const __half* inp_ptr = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    const __half* w_ptr   = reinterpret_cast<const __half*>(weight.data_ptr<at::Half>());
    const __half* b_ptr   = reinterpret_cast<const __half*>(bias.data_ptr<at::Half>());
    __half* out_ptr        = reinterpret_cast<__half*>(output.data_ptr<at::Half>());

    groupnorm_kernel<BLOCK_SIZE><<<grid, block>>>(
        inp_ptr, w_ptr, b_ptr, out_ptr,
        B, C, H, W, G, eps);
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA error: ") + cudaGetErrorString(err));
    }
    return output;
}
