    Drop‑in replacement for torch.nn.GroupNorm using a custom fused kernel.
    All tensors are fp16 on CUDA.
    """
    def __init__(self, num_features: int, num_groups: int, eps: float = 1e-5):
        super().__init__()
        self.num_features = num_features
        self.num_groups = num_groups
        self.eps = eps
        # Parameters stored in fp32 for optimizer stability, cast to fp16 at forward
        self.weight_fp32 = nn.Parameter(torch.ones(num_features, dtype=torch.float32))
        self.bias_fp32   = nn.Parameter(torch.zeros(num_features, dtype=torch.float32))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is on CUDA and fp16
        x_fp16 = x.to(device='cuda', dtype=torch.float16, non_blocking=False)

        # Cast parameters to fp16 on the same device
        weight_fp16 = self.weight_fp32.to(device='cuda', dtype=torch.float16, non_blocking=False)
        bias_fp16   = self.bias_fp32.to(device='cuda', dtype=torch.float16, non_blocking=False)

        out_fp16 = groupnorm_ext.groupnorm_cuda(
            x_fp16, weight_fp16, bias_fp16, self.num_groups, self.eps
        )
        # Preserve original dtype of the input tensor
        return out_fp16.to(x.dtype)
